import {nativeXrpNotification,sendNativeXrpAPNs} from './apns-gateway.mjs';
const PREFIX='cw-native-outbox-v1:',USAGE='cw-native-usage-v1:';
const encoder=new TextEncoder();
const utcDay=now=>new Date(now).toISOString().slice(0,10);
const digest=async(input,cryptoImpl)=>[...new Uint8Array(await cryptoImpl.subtle.digest('SHA-256',encoder.encode(input)))]
  .map(b=>b.toString(16).padStart(2,'0')).join('');

/**
 * Prepared APNs notifications reuse the exact events generated by the existing
 * evaluateRule() state machine. The host must write these outbox records inside
 * the SAME transaction as its Web Push event/state update, then drain separately.
 * This module never reads prices, polls markets, or guesses a crossing.
 */
export class NativeXrpOutbox{
 constructor({storage,registry,now=()=>Date.now(),cryptoImpl=globalThis.crypto,
   sender=sendNativeXrpAPNs,settings=null,maxDailyPerDevice=20}={}){
  if(!storage?.get||!storage?.put||!storage?.delete||!storage?.list||!storage?.transaction||!registry?.devices)throw Error('Native outbox storage missing');
  if(!Number.isInteger(maxDailyPerDevice)||maxDailyPerDevice<1||maxDailyPerDevice>20)throw Error('Invalid push allowance');
  this.storage=storage;this.registry=registry;this.now=now;this.crypto=cryptoImpl;
  this.sender=sender;this.settings=settings;this.daily=maxDailyPerDevice;this.queue=Promise.resolve();
 }
 locked(fn){const result=this.queue.then(fn,fn);this.queue=result.catch(()=>{});return result;}
 async prepare(parentId,verifiedEvent){
  if(!verifiedEvent||typeof verifiedEvent.id!=='string'||verifiedEvent.id.length>200)
    throw Error('A verified crossing identifier is required');
  const devices=await this.registry.devices(parentId),now=this.now(),jobs=[];
  for(const device of devices){
   const eventId=await digest(parentId+':'+verifiedEvent.id+':'+device.id,this.crypto);
   const event={...verifiedEvent,type:'threshold',eventId,expiresAt:now+120000};
   // Strictly reject unsupported assets, threshold values and stale observations.
   nativeXrpNotification(event,now);
   jobs.push({id:eventId,parentId,nativeId:device.id,event,expiresAt:event.expiresAt,
     createdAt:now,status:'queued',attempts:0,nextAttemptAt:now});
  }
  return jobs;
 }
 async saveInTransaction(tx,jobs){
  for(const job of jobs)await tx.put(PREFIX+job.id,job);
 }
 async enqueue(parentId,event){
  const jobs=await this.prepare(parentId,event);
  await this.storage.transaction(async tx=>this.saveInTransaction(tx,jobs));
  return jobs.length;
 }
 async cancelParent(parentId){
  const items=await this.storage.list({prefix:PREFIX});
  await this.storage.transaction(async tx=>{
   for(const [key,job] of items)if(job.parentId===parentId)await tx.delete(key);
  });
 }
 async drain(){
  return this.locked(async()=>{
   if(!this.settings?.teamId||!this.settings?.keyId||!this.settings?.privateKeyPEM||
      !this.settings?.bundleId||!['sandbox','production'].includes(this.settings.environment))return {sent:0,blocked:true};
   let sent=0,failed=0;
   const jobs=await this.storage.list({prefix:PREFIX});
   for(const [key,job] of [...jobs].slice(0,25)){
    const now=this.now();
    if(job.nextAttemptAt>now)continue;
    if(job.expiresAt<=now||job.attempts>=3){
     await this.storage.delete(key);continue;
    }
    const device=(await this.registry.devices(job.parentId)).find(d=>d.id===job.nativeId);
    if(!device){await this.storage.delete(key);continue;}
    const usageKey=USAGE+device.id+':'+utcDay(now);
    const usage=await this.storage.get(usageKey)||{count:0};
    if(usage.count>=this.daily){await this.storage.delete(key);continue;}
    const reserved={...job,status:'dispatching',attempts:job.attempts+1,nextAttemptAt:now+15000};
    // Persist a request reservation and quota BEFORE contacting APNs.
    await this.storage.transaction(async tx=>{
     await tx.put(key,reserved);await tx.put(usageKey,{count:usage.count+1});
    });
    try{
     const outcome=await this.sender({event:job.event,token:device.apnsToken,
       ...this.settings,now,timeoutMs:10000});
     if(outcome?.accepted===true){
      await this.storage.delete(key);sent++;continue;
     }
     throw Error('Unconfirmed APNs request');
    }catch{
     failed++;
     if(reserved.attempts>=3||this.now()+15000>=job.expiresAt)await this.storage.delete(key);
     else await this.storage.put(key,{...reserved,status:'retry',nextAttemptAt:this.now()+15000});
    }
   }
   return {sent,failed,blocked:false};
  });
 }
}
